import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { sql } from "drizzle-orm";
import { describe, expect, it } from "vitest";
import { cityKey } from "@/lib/playbookUrls";
import { db } from "./db/client";

// `saved_days.cities_folded` is generated by `tc_city_key` (migration 0077), and
// Discover asks it with keys folded by `cityKey`. If the two ever fold one city
// differently, that city's days silently drop out of Discover — so this holds
// them equal over every input it can afford to, not over a few examples.

const CONTENT = fileURLToPath(new URL("../../../../content", import.meta.url));

/** Every `city` string in the content bundles: the cities production actually holds. */
function contentCities(dir: string, into = new Set<string>()): Set<string> {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) contentCities(path, into);
    else if (entry.isFile() && entry.name.endsWith(".json")) collect(JSON.parse(readFileSync(path, "utf8")), into);
  }
  return into;
}

function collect(value: unknown, into: Set<string>): void {
  if (Array.isArray(value)) for (const item of value) collect(item, into);
  else if (value !== null && typeof value === "object") {
    for (const [key, inner] of Object.entries(value)) {
      if (key === "city" && typeof inner === "string") into.add(inner);
      else collect(inner, into);
    }
  }
}

/** Every BMP code point but the surrogates, alone and between two ASCII letters. */
function everyBmpCharacter(): string[] {
  const out: string[] = [];
  for (let cp = 0x01; cp <= 0xffff; cp += 1) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    const ch = String.fromCharCode(cp);
    out.push(ch, `Ab${ch}Cd`);
  }
  return out;
}

async function sqlKeys(cities: string[]): Promise<string[]> {
  const rows = await db.execute<{ key: string }>(sql`
    select public.tc_city_key(city) as key
    from unnest(${sql.param(cities)}::text[]) with ordinality as t(city, n)
    order by n
  `);
  return rows.rows.map((row) => row.key);
}

function mismatches(cities: string[], keys: string[]): Array<{ city: string; ts: string; sql: string }> {
  return cities
    .map((city, i) => ({ city, ts: cityKey(city), sql: keys[i]! }))
    .filter(({ ts, sql: fromSql }) => ts !== fromSql);
}

describe("tc_city_key, the SQL fold, is cityKey", () => {
  it("folds every content city as cityKey does", async () => {
    const cities = [...contentCities(CONTENT)];
    // A guard against the walk finding nothing and the test passing over it.
    expect(cities.length).toBeGreaterThan(100);
    expect(mismatches(cities, await sqlKeys(cities))).toEqual([]);
  });

  it("folds the spellings Discover must merge, and the edges of the slug", async () => {
    const cities = [
      "Kyoto", "kyoto", "KYOTO", "São Paulo", "Sao Paulo", "SÃO PAULO", "Wrocław", "WROCŁAW",
      "Ærø", "ÆRØ", "Straße", "STRASSE", "Þingvellir", "Œuvre", "Đà Nẵng", "İstanbul", "Ǿresund",
      "東京", "Москва", "---", " Kyoto ", "é", "Ｋｙｏｔｏ", "Kelvin",
      // Cut at 60 and the trailing hyphen dropped after the cut.
      `${"a".repeat(59)} b`, `${"a".repeat(60)}b`, `${"x".repeat(80)}`,
    ];
    expect(mismatches(cities, await sqlKeys(cities))).toEqual([]);
    expect(new Set((await sqlKeys(["Kyoto", "kyoto", "KYOTO"])))).toEqual(new Set(["kyoto"]));
    expect(new Set(await sqlKeys(["São Paulo", "Sao Paulo"]))).toEqual(new Set(["sao-paulo"]));
  });

  it("folds every BMP character as cityKey does", async () => {
    const cities = everyBmpCharacter();
    expect(mismatches(cities, await sqlKeys(cities))).toEqual([]);
  });

  it("generates the column as the distinct keys of `cities`", async () => {
    const rows = await db.execute<{ keys: string[] }>(sql`
      select public.tc_city_keys(${sql.param(["Kyoto", "kyoto", "東京", "São Paulo"])}::text[]) as keys
    `);
    expect([...rows.rows[0]!.keys].sort()).toEqual(["kyoto", "sao-paulo", "東京"]);
    const empty = await db.execute<{ keys: string[] }>(sql`select public.tc_city_keys('{}'::text[]) as keys`);
    expect(empty.rows[0]!.keys).toEqual([]);
  });
});
